    gap_cents: -100_000,
    runway_state: 'finite',
    runway_deci_months: deciMonths,
    // gap must read positive for the spending driven bands, so the
    // object carries a spending above income gap next to a finite deci.
    ...(deciMonths > 0 ? { gap_cents: 100_000 } : {}),
  })
}

